-- 159 — Executor de análises, catálogos privados e duas roles (#4130).
-- Fonte: platafirma-casa-espelho@4-compromisso/vinculo/analise.
-- Aplicação: release migrar aplicar rag, depois de 158, antes do verbo.
-- Idempotente. As senhas são cunhadas por release migrar senha, fora do arquivo.
-- Rollback: migração própria, depois de retirar o verbo, remover os catálogos
-- e as duas roles; descarte de dados exige autorização do dono.
SET LOCAL lock_timeout = '5s';
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='analise_extracao') THEN
    CREATE ROLE analise_extracao;
  END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='analise_publicacao') THEN
    CREATE ROLE analise_publicacao;
  END IF;
END $$;
ALTER ROLE analise_extracao LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE
  NOREPLICATION NOBYPASSRLS NOINHERIT CONNECTION LIMIT 2;
ALTER ROLE analise_publicacao LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE
  NOREPLICATION NOBYPASSRLS NOINHERIT CONNECTION LIMIT 2;
ALTER ROLE analise_extracao SET default_transaction_read_only = on;
ALTER ROLE analise_extracao SET statement_timeout = '60s';
ALTER ROLE analise_extracao SET lock_timeout = '2s';
ALTER ROLE analise_extracao SET idle_in_transaction_session_timeout = '15s';
ALTER ROLE analise_extracao SET work_mem = '8MB';
ALTER ROLE analise_extracao SET temp_file_limit = '256MB';
ALTER ROLE analise_extracao SET max_parallel_workers_per_gather = 0;
COMMENT ON ROLE analise_extracao IS 'Extrai somente as colunas autorizadas; sem acesso ao destino analítico. 159.';
COMMENT ON ROLE analise_publicacao IS 'Publica somente no schema analise; sem leitura das origens. 159.';
DO $$ BEGIN
  EXECUTE format('GRANT CONNECT ON DATABASE %I TO analise_extracao, analise_publicacao', current_database());
END $$;
CREATE SCHEMA IF NOT EXISTS analise AUTHORIZATION analise_publicacao;
REVOKE ALL ON SCHEMA analise FROM PUBLIC;
REVOKE ALL ON SCHEMA analise FROM analise_extracao;
GRANT USAGE, CREATE ON SCHEMA analise TO analise_publicacao;
GRANT USAGE ON SCHEMA acervo TO analise_extracao;
REVOKE ALL ON ALL TABLES IN SCHEMA acervo FROM analise_extracao, analise_publicacao;
GRANT SELECT (evento_id, ts, cadeira, sessao_id, ordem_id) ON acervo.log TO analise_extracao;
GRANT SELECT (evento_id, tool, ato, exit_code, classe, dur_ms, turno_fonte) ON acervo.log_giro TO analise_extracao;

CREATE TABLE IF NOT EXISTS analise.execucao (
    id text PRIMARY KEY,
    sujeito text NOT NULL,
    sessao text NOT NULL,
    ordem text NOT NULL,
    ato text NOT NULL,
    estado text NOT NULL DEFAULT 'ativa' CHECK (estado IN ('ativa','pronta','incompleta','reprovada','divergente')),
    iniciada_em timestamptz NOT NULL DEFAULT clock_timestamp(),
    terminada_em timestamptz,
    temporarios_ate timestamptz,
    origem_id text REFERENCES analise.execucao(id),
    manifesto jsonb NOT NULL DEFAULT '{}',
    causa text
);
ALTER TABLE analise.execucao OWNER TO analise_publicacao;
REVOKE ALL ON analise.execucao FROM PUBLIC;
COMMENT ON TABLE analise.execucao IS 'Catálogo execucao do executor de análises. 159.';
COMMENT ON COLUMN analise.execucao.id IS 'Identificador opaco da execução. 159.';
COMMENT ON COLUMN analise.execucao.sujeito IS 'Sujeito autorizado da execução. 159.';
COMMENT ON COLUMN analise.execucao.sessao IS 'Sessão que abriu a execução. 159.';
COMMENT ON COLUMN analise.execucao.ordem IS 'Ordem que abriu a execução. 159.';
COMMENT ON COLUMN analise.execucao.ato IS 'Etapa executada. 159.';
COMMENT ON COLUMN analise.execucao.estado IS 'Estado durável da execução. 159.';
COMMENT ON COLUMN analise.execucao.iniciada_em IS 'Início da execução. 159.';
COMMENT ON COLUMN analise.execucao.terminada_em IS 'Término da execução. 159.';
COMMENT ON COLUMN analise.execucao.temporarios_ate IS 'Vencimento dos temporários. 159.';
COMMENT ON COLUMN analise.execucao.origem_id IS 'Execução preservada pelo refazer. 159.';
COMMENT ON COLUMN analise.execucao.manifesto IS 'Procedência e medidas sem conteúdo de linha. 159.';
COMMENT ON COLUMN analise.execucao.causa IS 'Código de causa sem diagnóstico da receita. 159.';

CREATE TABLE IF NOT EXISTS analise.base (
    id text PRIMARY KEY,
    execucao_id text NOT NULL UNIQUE REFERENCES analise.execucao(id),
    sujeito text NOT NULL,
    receita text NOT NULL,
    n bigint NOT NULL CHECK(n >= 0),
    expires_at timestamptz,
    guarda jsonb NOT NULL,
    manifesto jsonb NOT NULL
);
ALTER TABLE analise.base OWNER TO analise_publicacao;
REVOKE ALL ON analise.base FROM PUBLIC;
COMMENT ON TABLE analise.base IS 'Catálogo base do executor de análises. 159.';
COMMENT ON COLUMN analise.base.id IS 'Identificador opaco da versão da base. 159.';
COMMENT ON COLUMN analise.base.execucao_id IS 'Execução que publicou a base. 159.';
COMMENT ON COLUMN analise.base.sujeito IS 'Sujeito proprietário da base. 159.';
COMMENT ON COLUMN analise.base.receita IS 'Receita de preparação. 159.';
COMMENT ON COLUMN analise.base.n IS 'Tamanho da população preparada. 159.';
COMMENT ON COLUMN analise.base.expires_at IS 'Vencimento da base ou nulo até descarte. 159.';
COMMENT ON COLUMN analise.base.guarda IS 'Regra e motivo da guarda. 159.';
COMMENT ON COLUMN analise.base.manifesto IS 'Manifesto da publicação. 159.';

CREATE TABLE IF NOT EXISTS analise.resultado (
    id text PRIMARY KEY,
    execucao_id text NOT NULL UNIQUE REFERENCES analise.execucao(id),
    base_id text NOT NULL REFERENCES analise.base(id),
    sujeito text NOT NULL,
    receita text NOT NULL,
    expires_at timestamptz,
    guarda jsonb NOT NULL,
    manifesto jsonb NOT NULL
);
ALTER TABLE analise.resultado OWNER TO analise_publicacao;
REVOKE ALL ON analise.resultado FROM PUBLIC;
COMMENT ON TABLE analise.resultado IS 'Catálogo resultado do executor de análises. 159.';
COMMENT ON COLUMN analise.resultado.id IS 'Identificador opaco do resultado. 159.';
COMMENT ON COLUMN analise.resultado.execucao_id IS 'Execução que publicou o resultado. 159.';
COMMENT ON COLUMN analise.resultado.base_id IS 'Base que limita a guarda do resultado. 159.';
COMMENT ON COLUMN analise.resultado.sujeito IS 'Sujeito proprietário do resultado. 159.';
COMMENT ON COLUMN analise.resultado.receita IS 'Receita de análise. 159.';
COMMENT ON COLUMN analise.resultado.expires_at IS 'Vencimento limitado pelo da base. 159.';
COMMENT ON COLUMN analise.resultado.guarda IS 'Regra e motivo da guarda. 159.';
COMMENT ON COLUMN analise.resultado.manifesto IS 'Manifesto da publicação. 159.';

CREATE TABLE IF NOT EXISTS analise.tabela (
    objeto_id text NOT NULL,
    nome text NOT NULL,
    fisica text NOT NULL UNIQUE,
    colunas jsonb NOT NULL,
    ordem jsonb NOT NULL,
    linhas bigint NOT NULL,
    sha256 text NOT NULL,
    bytes bigint NOT NULL,
    PRIMARY KEY (objeto_id,nome)
);
ALTER TABLE analise.tabela OWNER TO analise_publicacao;
REVOKE ALL ON analise.tabela FROM PUBLIC;
COMMENT ON TABLE analise.tabela IS 'Catálogo tabela do executor de análises. 159.';
COMMENT ON COLUMN analise.tabela.objeto_id IS 'Base ou resultado proprietário. 159.';
COMMENT ON COLUMN analise.tabela.nome IS 'Nome lógico declarado. 159.';
COMMENT ON COLUMN analise.tabela.fisica IS 'Nome interno no schema analise. 159.';
COMMENT ON COLUMN analise.tabela.colunas IS 'Colunas e tipos declarados. 159.';
COMMENT ON COLUMN analise.tabela.ordem IS 'Chave de ordem total. 159.';
COMMENT ON COLUMN analise.tabela.linhas IS 'Quantidade de linhas. 159.';
COMMENT ON COLUMN analise.tabela.sha256 IS 'Hash da serialização canônica. 159.';
COMMENT ON COLUMN analise.tabela.bytes IS 'Tamanho da CSV canônica. 159.';

CREATE TABLE IF NOT EXISTS analise.projecao (
    objeto_id text NOT NULL,
    nome text NOT NULL,
    conteudo bytea NOT NULL,
    sha256 text NOT NULL,
    largura integer NOT NULL,
    altura integer NOT NULL,
    PRIMARY KEY (objeto_id,nome)
);
ALTER TABLE analise.projecao OWNER TO analise_publicacao;
REVOKE ALL ON analise.projecao FROM PUBLIC;
COMMENT ON TABLE analise.projecao IS 'Catálogo projecao do executor de análises. 159.';
COMMENT ON COLUMN analise.projecao.objeto_id IS 'Base ou resultado proprietário. 159.';
COMMENT ON COLUMN analise.projecao.nome IS 'Nome declarado da projeção. 159.';
COMMENT ON COLUMN analise.projecao.conteudo IS 'Imagem PNG canônica. 159.';
COMMENT ON COLUMN analise.projecao.sha256 IS 'Hash da imagem. 159.';
COMMENT ON COLUMN analise.projecao.largura IS 'Largura em pixels. 159.';
COMMENT ON COLUMN analise.projecao.altura IS 'Altura em pixels. 159.';

CREATE INDEX IF NOT EXISTS resultado_base_idx ON analise.resultado(base_id);
CREATE INDEX IF NOT EXISTS execucao_estado_idx ON analise.execucao(estado);
DO $$
DECLARE r record; n integer;
BEGIN
  FOR r IN SELECT * FROM pg_roles WHERE rolname IN ('analise_extracao','analise_publicacao') LOOP
    IF r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication
       OR r.rolbypassrls OR r.rolinherit OR NOT r.rolcanlogin THEN
      RAISE EXCEPTION '159: atributos privilegiados em %', r.rolname;
    END IF;
    IF EXISTS(SELECT FROM pg_auth_members WHERE member=r.oid) THEN
      RAISE EXCEPTION '159: role % herda outro papel', r.rolname;
    END IF;
  END LOOP;
  SELECT count(*) INTO n FROM pg_tables WHERE schemaname='analise'
    AND tablename IN ('execucao','base','resultado','tabela','projecao');
  IF n<>5 THEN RAISE EXCEPTION '159: catálogos ausentes'; END IF;
  IF has_schema_privilege('analise_extracao','analise','USAGE')
     OR has_schema_privilege('analise_publicacao','acervo','CREATE') THEN
    RAISE EXCEPTION '159: fronteira de schema aberta';
  END IF;
  IF has_table_privilege('analise_extracao','acervo.log','SELECT')
     OR has_table_privilege('analise_publicacao','acervo.log','SELECT')
     OR NOT has_column_privilege('analise_extracao','acervo.log','ts','SELECT') THEN
    RAISE EXCEPTION '159: grants por coluna fora do contrato';
  END IF;
  RAISE NOTICE '159 aceite: schema analise privado, cinco catálogos e duas roles sem herança, extração por coluna e publicação só no destino';
END $$;
